steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
    query {
      teams(name: \"Web\") {
        nodes {
          id
          name
          workflowStates {
            nodes {
              id
              name
            }
          }
          labels {
            nodes {
              id
              name
            }
          }
        }
      }
      users {
        nodes {
          id
          name
        }
        where: { name: { eq: \"Maya Chen\" } }
      }
    }"
  }'
